(function(){'use strict';const RIA=window.RIA;let challenge=null,grant=null;
async function request(route,data){let response;try{response=await fetch('/api/auth/'+route,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(15000)});}catch(e){throw Object.assign(new Error('ارتباط برقرار نشد، دوباره امتحان کن'),{code:'network'});}let result;try{result=await response.json();}catch(e){throw new Error('پاسخ سرور رو نتونستیم بخونیم، دوباره امتحان کن');}if(!response.ok)throw Object.assign(new Error(result.error||'درخواست انجام نشد'),{code:result.code||(response.status===401?(route==='login'?'credentials':'badcode'):response.status===409?'exists':response.status===429?'limited':'request'),retryAfter:result.retryAfter});return result;}
const purposeOf=p=>p==='signup'?'register':p;
RIA.api={async sendOtp(mobile,purpose){grant=null;RIA.startSmsCapture();const p=purposeOf(purpose);let r;try{r=await request('otp/request',{phone:mobile,purpose:p});}catch(e){RIA.stopSmsCapture();throw e;}challenge={mobile,purpose:p,id:r.challengeId};return r;},async verifyOtp(mobile,code,purpose){const p=purposeOf(purpose);if(!challenge||challenge.mobile!==mobile||challenge.purpose!==p)throw new Error('یه کد تازه بگیر');const r=await request('otp/verify',{challengeId:challenge.id,code,purpose:p});grant={mobile,purpose:p,token:r.registrationToken||r.resetToken};return r;},loginWithPassword:(phone,password)=>request('login',{phone,password}),async setPassword(mobile,password,purpose){const p=purposeOf(purpose);if(!grant||grant.mobile!==mobile||grant.purpose!==p||!grant.token)throw new Error('اول شماره‌ات رو تأیید کن');const token=grant.token;const r=await request(p==='register'?'register':'password/reset',p==='register'?{registrationToken:token,password}:{resetToken:token,password});grant=null;return r;}};
})();